class LibraryRepo:
    def __init__(self, db):
        self.db = db

    def books(self):
        return self.db.select_books()

    def author(self, author_id):
        return self.db.select_author(author_id)

    def authors(self, author_ids):
        """{id: row} for just these authors, in one query."""
        return {row["id"]: row for row in self.db.select_authors(author_ids)}

    def all_authors(self):
        return {row["id"]: row for row in self.db.select_all_authors()}

