import unittest

from db import FakeDB
from report import build_report
from repo import LibraryRepo


class Regression(unittest.TestCase):
    def test_only_the_authors_that_are_needed_are_read(self):
        authors = {i: {"id": i, "name": "Author %d" % i} for i in range(1, 401)}
        books = [{"title": "T%d" % n, "author_id": n + 1} for n in range(5)]
        db = FakeDB(books, authors)
        build_report(LibraryRepo(db))
        self.assertLessEqual(db.rows_read, 5 + 5)

    def test_a_book_with_an_unknown_author_is_reported_as_unknown(self):
        db = FakeDB([{"title": "Orphan", "author_id": 99}], {1: {"id": 1, "name": "Ada"}})
        self.assertEqual(build_report(LibraryRepo(db)), ["Orphan by Unknown"])

    def test_books_keep_their_order(self):
        authors = {1: {"id": 1, "name": "Ada"}, 2: {"id": 2, "name": "Bob"}}
        books = [{"title": "Z", "author_id": 2}, {"title": "A", "author_id": 1}]
        self.assertEqual(build_report(LibraryRepo(FakeDB(books, authors))), ["Z by Bob", "A by Ada"])

    def test_no_books_means_no_author_query(self):
        db = FakeDB([], {1: {"id": 1, "name": "Ada"}})
        self.assertEqual(build_report(LibraryRepo(db)), [])
        self.assertEqual(db.queries, 1)

